WITH unpacked AS (SELECT id, customer_id, created_at, coupon_codes, items, ship_to, ship_to.city AS ship_city, COALESCE(attributes['utm_source'], 'direct') AS utm_source_or_default, EXISTS(items, li -> li.price > 100) AS has_premium_item, FORALL(items, li -> li.qty <= 5) AS all_small_qty FROM carts) SELECT customer_id, DATE_TRUNC('DAY', created_at) AS activity_day, ship_city, COUNT(*) AS num_rows, COUNT(CASE WHEN ship_city = 'Chiang Mai' THEN 1 END) AS chiang_mai_count, COUNT_IF(ship_city = 'Berlin') AS berlin_events, COUNT(*) FILTER (WHERE ship_city = 'Chiang Mai') AS chiang_mai_rows FROM unpacked GROUP BY customer_id, DATE_TRUNC('DAY', created_at), ship_city ORDER BY chiang_mai_rows DESC
